    (1, '3659016341', 898, 2, '1010201001', 1, 0, 1000, null, null, null, 'I'),
    (1, '3659016341', 899, 1, '1010102001', 1, 48300, 0, null, null, null, 'I'),
    (1, '3659016341', 899, 2, '1010201001', 1, 0, 48300, null, null, null, 'I'),
